# This file is not generated by Stainless and is preserved across codegen runs.
# It checks that every hand-written *_and_poll helper accepts each parameter of
# the generated method it wraps (GCLOUD2-30502).
#
# The helpers in resources/**/*_custom.py repeat the wrapped method's parameter
# list. When the spec adds a parameter, codegen updates the wrapped method but
# not the helper, so passing that parameter to the helper raises a TypeError.
from __future__ import annotations

import inspect
import pkgutil
import importlib
from typing import Any, Iterator

import pytest

import gcore.resources

# Add a name here only when a helper sets that argument itself instead of taking it from the caller.
_IGNORED = {"self"}


def _helpers() -> Iterator[Any]:
    for info in pkgutil.walk_packages(gcore.resources.__path__, "gcore.resources."):
        module = importlib.import_module(info.name)
        for cls_name, cls in inspect.getmembers(module, inspect.isclass):
            # Generated resource classes only; the mixins are reached through them.
            if cls.__module__ != module.__name__ or not cls_name.endswith("Resource"):
                continue
            for name in sorted(dir(cls)):
                if name.endswith("_and_poll"):
                    yield pytest.param(cls, name, id=f"{module.__name__}.{cls_name}.{name}")


@pytest.mark.parametrize("cls, helper", list(_helpers()))
def test_and_poll_accepts_wrapped_params(cls: type, helper: str) -> None:
    wrapped = helper[: -len("_and_poll")]
    assert hasattr(cls, wrapped), f"{cls.__name__}.{helper} has no generated {wrapped} method to wrap"

    helper_params = inspect.signature(getattr(cls, helper)).parameters
    wrapped_params = inspect.signature(getattr(cls, wrapped)).parameters
    missing = sorted(set(wrapped_params) - set(helper_params) - _IGNORED)

    assert not missing, (
        f"{cls.__name__}.{helper} does not accept {', '.join(missing)}, which {cls.__name__}.{wrapped} accepts. "
        f"Add them to the helper in {getattr(cls, helper).__module__} and forward them to {wrapped}."
    )
